sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	// Created as part of MSSCUSTODY-7509
	var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
	if (tradeGR.get(current.trade_id)) { 
        // Fetch BPI record of this trade
		//gs.info('In BR - Trade ID ' +current.trade_id );
		gs.info('YY In BR - tradeGR.business_process_instance_id Trade ID '+ tradeGR.sys_id);

        var bpiGR = new GlideRecord('x_hsb11_mss_custod_mss_custody_business_process_instance');
        if (bpiGR.get('trade_id', tradeGR.sys_id)) {
			gs.info('YY In BR IN - BPI' + bpiGR.sys_id);
            bpiGR.case_counter = bpiGR.case_counter + 1;
            bpiGR.update();
			gs.info('YY In BR IN - BPI Counter ' + bpiGR.case_counter);
        }else{
			gs.info('YY In BR IN - No Record '+ bpiGR.get('trade_id', tradeGR.sys_id));
		}
    }

})(current, previous);
